import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Recorrido, tono, Chip, Regla, Contador, Ondas, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const BAT1 = en('batería'), BAT2 = en('batería', 2), LA = en('La'), SOL1 = en('Sol'), SOL2 = en('Sol', 2);
const CARR = en('Carrington'), DIBUJ = en('dibujaba'), MANCH = en('manchas'), PUNTOS = en('puntos'), BLANCA = en('blanca');
const DURARON = en('Duraron'), CINCO = en('cinco'), MINUTOS = en('minutos'), NADIE = en('Nadie');
const EXPL = en('explosión'), GIG = en('gigante'), NUBE = en('nube'), TIERRA = en('Tierra');
const LLEGO = en('Llegó'), DIECI = en('diecisiete'), HORAS1 = en('horas'), DESP = en('después');
const CIELO = en('cielo'), AURORAS = en('auroras'), SUR = en('sur'), TROPICO = en('trópico');
const MONT = en('montañas'), LEVANT = en('levantaron'), DESAY = en('desayuno'), CREIAN = en('Creían'), AMAN = en('amanecido');
const LINEAS = en('líneas'), CHISPAS = en('chispas'), OPER1 = en('operadores'), DESCARG = en('descargas'), PAPELES = en('papeles'), PREND = en('prendieron');
const ENTRE = en('Entre'), BOSTON = en('Boston'), PORTLAND = en('Portland'), OPER2 = en('operadores', 2), DESCON = en('desconectaron'), BATERIAS = en('baterías');
const SIGUIE = en('siguieron'), MENS = en('mensajes'), HORAS2 = en('horas', 2), CORRIENTE = en('corriente'), TORM1 = en('tormenta'), FUE = en('Fue'), TORM2 = en('tormenta', 2), FUERTE = en('fuerte');
const SI = en('Si'), GOLP = en('golpearía'), SATEL = en('satélites'), REDES = en('redes'), ELEC = en('eléctricas'), SENAL = en('señal'), CEL = en('celular');
const DALE = en('Dale'), NADA = en('nada'), FUNC = en('funciona');

const AZUL = '#3DB8FF';
const AZUL_C = '#9BE3FF';
const SOLC = '#FF8A2A';
const abre = (s: number, a: number, b: number, c: number) => interpolate(s, [a, b, c], [0, 1, 0], {...clamp, easing: Easing.inOut(Easing.sin)});

const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 3000}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

type Parada = {t: number; x: number; y: number; zoom: number};
const Lugar: React.FC<{tipo: 'piel' | 'celulas' | 'fibra' | 'papel'; base: string; linea: string; luz: string; semilla: number; bx: number; by: number; bc: string; paradas: Parada[]; w?: number; children: React.ReactNode}> = ({tipo, base, linea, luz, semilla, bx, by, bc, paradas, w, children}) => (
  <AbsoluteFill style={{background: '#0A0A12'}}>
    <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
    <Camara paradas={paradas}>
      <Brillo x={bx} y={by} r={720} color={bc} />
      <Mundo w={w}>{children}</Mundo>
    </Camara>
  </AbsoluteFill>
);

// ---------- piezas dibujadas ----------
// la chispa azul: protagonista, con cara
const Chispa: React.FC<{x: number; y: number; sc?: number; ang?: number; op?: number}> = ({x, y, sc = 1, ang = 0, op = 1}) => {
  const {s} = useS();
  const p = 1 + 0.09 * Math.sin(s * 9 + x * 0.02);
  const pts = Array.from({length: 16}).map((_, i) => {
    const r = i % 2 ? 54 : 112 + 14 * Math.sin(s * 14 + i);
    const a = (i / 16) * Math.PI * 2 + s * 0.8;
    return `${Math.cos(a) * r},${Math.sin(a) * r}`;
  }).join(' ');
  return (
    <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc * p})`} opacity={op}>
      <defs><radialGradient id="chG" cx="50%" cy="50%" r="50%"><stop offset="0%" stopColor="#FFFFFF" /><stop offset="38%" stopColor="#9BE3FF" /><stop offset="100%" stopColor="#3DB8FF" stopOpacity={0} /></radialGradient></defs>
      <circle r={150} fill="url(#chG)" opacity={0.75} />
      <polygon points={pts} fill="#BDEBFF" stroke="#3DB8FF" strokeWidth={5} strokeLinejoin="round" />
      <circle r={44} fill="#F2FBFF" stroke="#3DB8FF" strokeWidth={6} />
      {[-1, 1].map((k) => <g key={k}><ellipse cx={k * 15} cy={-4} rx={6.5} ry={9} fill="#12365A" /><circle cx={k * 15 + 2} cy={-7} r={2.6} fill="#fff" /></g>)}
      <path d="M -11 14 Q 0 24 11 14" stroke="#12365A" strokeWidth={4.5} fill="none" strokeLinecap="round" />
    </g>
  );
};

// ramas de chispas que saltan
const Chisp: React.FC<{x: number; y: number; on: number; col?: string; n?: number; r?: number}> = ({x, y, on, col = AZUL_C, n = 7, r = 80}) => {
  const {s} = useS();
  if (on <= 0.01) return null;
  const f = Math.floor(s * 14);
  return (
    <g transform={`translate(${x} ${y})`} opacity={Math.min(1, on)}>
      {Array.from({length: n}).map((_, i) => {
        const a = h(i * 3 + f * 7) * Math.PI * 2;
        const l = r * (0.5 + h(i * 5 + f));
        const m = a + (h(i + f * 11) - 0.5) * 1.4;
        const p = `M 0 0 L ${Math.cos(a) * l * 0.4} ${Math.sin(a) * l * 0.4} L ${Math.cos(m) * l * 0.62} ${Math.sin(m) * l * 0.62} L ${Math.cos(a) * l} ${Math.sin(a) * l}`;
        return <g key={i}><path d={p} stroke={AZUL} strokeWidth={9} fill="none" opacity={0.35} strokeLinecap="round" strokeLinejoin="round" /><path d={p} stroke="#EAF9FF" strokeWidth={3.5} fill="none" strokeLinecap="round" strokeLinejoin="round" /></g>;
      })}
    </g>
  );
};

// hombre de época: operador con visor, minero con sombrero, astrónomo con patillas
const Hombre: React.FC<{x: number; y: number; sc?: number; dir?: number; saco?: string; chaleco?: string; gorro?: 'visor' | 'sombrero' | 'nada'; patillas?: boolean; bigote?: boolean; brazo?: number; boca?: number; piel?: string; pelo?: string; lapiz?: boolean; camina?: number; fase?: number}> = ({x, y, sc = 1, dir = 1, saco = '#5A6A8A', chaleco, gorro = 'nada', patillas = false, bigote = false, brazo = -12, boca = 0, piel = '#E3B08A', pelo = '#2A1E16', lapiz = false, camina = 0, fase = 0}) => {
  const {s} = useS();
  const sw = Math.sin(s * 8 + fase) * 16 * camina;
  return (
    <g transform={`translate(${x} ${y}) scale(${dir * sc} ${sc})`}>
      <ellipse cx={0} cy={4} rx={66} ry={10} fill="rgba(0,0,0,0.25)" />
      <rect x={-24} y={-124} width={20} height={124} rx={10} fill="#2C2C3A" transform={`rotate(${sw} -14 -124)`} />
      <rect x={4} y={-124} width={20} height={124} rx={10} fill="#2C2C3A" transform={`rotate(${-sw} 14 -124)`} />
      <rect x={-38} y={-252} width={76} height={140} rx={30} fill={saco} />
      {chaleco && <rect x={-28} y={-240} width={56} height={116} rx={20} fill={chaleco} />}
      <path d="M -16 -250 L 0 -194 L 16 -250 Z" fill="#F4EEDD" />
      <g transform={`rotate(${brazo} 28 -242)`}>
        <rect x={20} y={-242} width={17} height={104} rx={8} fill={saco} />
        {lapiz && <rect x={25} y={-150} width={7} height={40} rx={2} fill="#E8C13A" />}
        <circle cx={28.5} cy={-136} r={10} fill={piel} />
      </g>
      <circle cx={0} cy={-294} r={36} fill={piel} stroke="rgba(90,50,30,0.4)" strokeWidth={3} />
      <path d="M -36 -296 Q -34 -334 0 -332 Q 36 -334 36 -296 Q 12 -318 -36 -296 Z" fill={pelo} />
      {patillas && [-1, 1].map((k) => <ellipse key={k} cx={k * 33} cy={-284} rx={8} ry={19} fill={pelo} />)}
      {bigote && <path d="M -22 -272 Q -10 -282 0 -274 Q 10 -282 22 -272 Q 10 -268 0 -270 Q -10 -268 -22 -272 Z" fill={pelo} />}
      <circle cx={-12} cy={-296} r={3.5 + boca * 1.5} fill="#241410" /><circle cx={12} cy={-296} r={3.5 + boca * 1.5} fill="#241410" />
      {boca > 0.06 ? <ellipse cx={0} cy={-268} rx={7 + 4 * boca} ry={3 + 11 * boca} fill="#5A1A22" /> : !bigote && <path d="M -8 -274 Q 0 -268 8 -274" stroke="#7A3A2A" strokeWidth={3} fill="none" />}
      {gorro === 'visor' && <><path d="M -40 -308 Q 0 -342 40 -308 L 62 -302 L -62 -302 Z" fill="#3E8A55" stroke="#1E4A2A" strokeWidth={3} /><rect x={-42} y={-312} width={84} height={7} fill="#2A6A40" /></>}
      {gorro === 'sombrero' && <><ellipse cx={0} cy={-322} rx={64} ry={11} fill="#6A4A2A" stroke="#3A2410" strokeWidth={3} /><path d="M -34 -322 Q -34 -366 0 -366 Q 34 -366 34 -322 Z" fill="#7A5A32" stroke="#3A2410" strokeWidth={3} /></>}
    </g>
  );
};

// llave del telégrafo
const Llave: React.FC<{x: number; y: number; sc?: number; tap: number}> = ({x, y, sc = 1, tap}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`}>
    <rect x={-170} y={-14} width={340} height={30} rx={8} fill="#6A4220" stroke="#2A160A" strokeWidth={4} />
    <rect x={-130} y={-36} width={260} height={24} rx={8} fill="#C9A23F" stroke="#7A5E1A" strokeWidth={4} />
    <rect x={-100} y={-60} width={30} height={26} rx={6} fill="#B8902F" stroke="#7A5E1A" strokeWidth={3} />
    <circle cx={-85} cy={-48} r={11} fill="#EBD27A" stroke="#7A5E1A" strokeWidth={3} />
    <g transform={`rotate(${-5 + 6 * tap} -85 -48)`}>
      <rect x={-92} y={-76} width={250} height={16} rx={8} fill="#D9B24A" stroke="#7A5E1A" strokeWidth={3} />
      <ellipse cx={128} cy={-96} rx={36} ry={22} fill="#2A160A" stroke="#14080A" strokeWidth={3} />
      <rect x={120} y={-84} width={16} height={26} fill="#2A160A" />
    </g>
    <circle cx={96} cy={-30} r={10} fill="#EBD27A" stroke="#7A5E1A" strokeWidth={3} />
  </g>
);

// frasco de batería de vidrio con barra de zinc
const Frasco: React.FC<{x: number; y: number; viva: number}> = ({x, y, viva}) => {
  const {s} = useS();
  return (
    <g transform={`translate(${x} ${y})`}>
      <rect x={-46} y={-130} width={92} height={130} rx={14} fill="rgba(190,235,225,0.28)" stroke="#9ED8CC" strokeWidth={5} />
      <rect x={-40} y={-84} width={80} height={78} rx={10} fill={viva > 0.5 ? '#5FD6A0' : '#7A8A86'} opacity={0.5 + 0.35 * viva} />
      <rect x={-8} y={-152} width={16} height={110} rx={6} fill="#B8BCC4" stroke="#6A6E78" strokeWidth={3} />
      <circle cx={0} cy={-156} r={11} fill="#C98A3A" stroke="#6A4A1A" strokeWidth={3} />
      {viva > 0.5 && [0, 1, 2].map((i) => <circle key={i} cx={-18 + i * 18} cy={-20 - ((s * 38 + i * 24) % 56)} r={4} fill="rgba(255,255,255,0.7)" />)}
    </g>
  );
};

const Reloj: React.FC<{x: number; y: number; r: number; min: number}> = ({x, y, r, min}) => (
  <g transform={`translate(${x} ${y})`}>
    <circle r={r + 10} fill="#7A5A1A" stroke="#3A2A0A" strokeWidth={5} />
    <circle r={r} fill="#FFF6DC" stroke="#C9A23F" strokeWidth={4} />
    {Array.from({length: 12}).map((_, i) => <line key={i} x1={0} y1={-r + 6} x2={0} y2={-r + (i % 3 ? 14 : 22)} stroke="#3A2A0A" strokeWidth={i % 3 ? 3 : 5} transform={`rotate(${i * 30})`} />)}
    <line x1={0} y1={0} x2={0} y2={-r * 0.5} stroke="#2A160A" strokeWidth={7} strokeLinecap="round" transform={`rotate(${min / 12})`} />
    <line x1={0} y1={0} x2={0} y2={-r * 0.78} stroke="#2A160A" strokeWidth={4.5} strokeLinecap="round" transform={`rotate(${min})`} />
    <circle r={6} fill="#2A160A" />
  </g>
);

const Estrellas: React.FC<{n?: number; y0?: number; y1?: number}> = ({n = 70, y0 = 80, y1 = 1800}) => {
  const {s} = useS();
  return <>{Array.from({length: n}).map((_, i) => <circle key={i} cx={-120 + h(i * 2) * 1320} cy={y0 + h(i * 2 + 1) * (y1 - y0)} r={1.5 + h(i + 40) * 3} fill="#fff" opacity={0.4 + 0.5 * Math.abs(Math.sin(s * (1 + h(i) * 2) + i))} />)}</>;
};

// ---------- E1, E11 y E14: la oficina de telégrafo ----------
const Oficina: React.FC<{v: 1 | 2 | 3}> = ({v}) => {
  const {s, spr, lin} = useS();
  const tap = Math.sin(s * 21 + Math.sin(s * 5)) > 0.15 ? 1 : 0;
  const abierto = v === 1 ? lin(0.95, 1.25, 0, 1) : 1;
  const viva = 1 - abierto;
  const armA = v === 1 ? interpolate(s, [0, 0.35, 0.85, 1.05, 1.6], [-14, -14, -88, -88, -14], {...clamp, easing: Easing.inOut(Easing.sin)}) : -14 + 3 * Math.sin(s * 2);
  const wire = 'M 780 440 L 780 830 Q 780 1000 640 1100 L 520 1195';
  const chPath: [number, number][] = [[780, 450], [780, 830], [700, 1020], [600, 1130], [520, 1190]];
  const T2 = SIGUIE;
  const reloj = v === 2 ? 3000 + lin(HORAS2 - 0.3, HORAS2 + 1.3, 0, 2200, Easing.inOut(Easing.cubic)) : v === 3 ? 400 + s * 6 : 100 + s * 6;
  const lampara = v === 3 ? lin(FUNC - 0.2, FUNC + 0.3, 0, 1) : 0;
  const pasos = v === 1
    ? [{t: 0, x: 500, y: 1210, zoom: 1.3}, {t: BAT1 - 0.5, x: 500, y: 1200, zoom: 1.5}, {t: BAT1 + 0.55, x: 500, y: 1190, zoom: 1.85}]
    : v === 2
      ? [{t: T2 - 0.3, x: 650, y: 760, zoom: 1.15}, ...seguir(chPath, T2 + 0.3, TORM1 - 0.1, 1.45, 5), {t: TORM1 + 0.9, x: 500, y: 1190, zoom: 1.85}]
      : [{t: DALE - 0.2, x: 500, y: 1180, zoom: 1.2}, {t: BAT2 - 0.4, x: 500, y: 1190, zoom: 1.45}, {t: FUNC + 0.6, x: 500, y: 1190, zoom: 1.85}];
  return (
    <Lugar tipo="fibra" base="radial-gradient(circle at 50% 30%, #B47A3E 0%, #8A5A2B 55%, #3A2410 100%)" linea="rgba(60,30,10,0.5)" luz="rgba(255,210,140,0.25)" semilla={v + 20} bx={540} by={760} bc="rgba(255,205,130,0.55)" paradas={pasos}>
      {Array.from({length: 11}).map((_, i) => <line key={i} x1={-60 + i * 130} y1={200} x2={-60 + i * 130} y2={1260} stroke="rgba(40,20,5,0.4)" strokeWidth={5} />)}
      <rect x={-200} y={980} width={1500} height={20} fill="rgba(60,30,10,0.45)" />
      <Reloj x={330} y={600} r={84} min={reloj} />
      {/* ventana */}
      <svg x={650} y={460} width={260} height={360} viewBox="0 0 260 360" overflow="hidden">
        <defs>
          <linearGradient id={`cv${v}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={v === 1 ? '#FFB45A' : v === 2 ? '#0E2A3A' : '#0E1630'} /><stop offset="100%" stopColor={v === 1 ? '#FF8A2A' : v === 2 ? '#1A4A3E' : '#1E2A58'} /></linearGradient>
        </defs>
        <rect width={260} height={360} fill={`url(#cv${v})`} />
        {v === 1 && <circle cx={180 + 10 * Math.sin(s * 0.8)} cy={220} r={120} fill="#FFD27A" opacity={0.85} />}
        {v === 2 && [0, 1, 2].map((i) => <path key={i} d={`M ${-10 + i * 90} 360 Q ${30 + i * 90 + 20 * Math.sin(s * 2 + i)} 200 ${i * 90 + 50} 40`} stroke={i === 1 ? '#FF4FD8' : '#46FF9A'} strokeWidth={34} fill="none" opacity={0.5} strokeLinecap="round" />)}
        {v === 3 && Array.from({length: 14}).map((_, i) => <circle key={i} cx={h(i) * 250} cy={h(i + 9) * 340} r={2 + h(i + 4) * 2} fill="#fff" opacity={0.5 + 0.4 * Math.sin(s * 3 + i)} />)}
        <line x1={130} y1={0} x2={130} y2={360} stroke="#3A2410" strokeWidth={10} /><line x1={0} y1={170} x2={260} y2={170} stroke="#3A2410" strokeWidth={10} />
      </svg>
      <rect x={650} y={460} width={260} height={360} fill="none" stroke="#3A2410" strokeWidth={16} rx={6} />
      {/* lámpara colgante */}
      <line x1={540} y1={150} x2={540} y2={880} stroke="#2A160A" strokeWidth={5} />
      <path d="M 480 920 L 500 870 L 580 870 L 600 920 Z" fill="#3A2A18" stroke="#14080A" strokeWidth={3} />
      <circle cx={540} cy={930} r={24 + 4 * lampara} fill={lampara > 0.05 ? '#FFF6C0' : '#CFC59A'} opacity={0.6 + 0.4 * lampara} />
      {lampara > 0.05 && <circle cx={540} cy={930} r={150 * lampara} fill="rgba(255,240,170,0.28)" />}
      <Hombre x={210} y={1520} sc={1.35} dir={1} saco="#5A6A8A" gorro="visor" bigote brazo={armA} boca={v === 2 ? 0.8 : 0} />
      <rect x={-300} y={1250} width={1700} height={520} fill="#5A3A1C" stroke="#2A160A" strokeWidth={6} />
      <rect x={-300} y={1250} width={1700} height={22} fill="#C9A23F" />
      {[0, 1, 2].map((i) => <g key={i}><rect x={-60 + i * 460} y={1330} width={420} height={170} rx={10} fill="#6A4524" stroke="#2A160A" strokeWidth={5} /><rect x={80 + i * 460} y={1400} width={140} height={22} rx={11} fill="#C9A23F" stroke="#7A5E1A" strokeWidth={3} /><rect x={-60 + i * 460} y={1540} width={420} height={170} rx={10} fill="#6A4524" stroke="#2A160A" strokeWidth={5} /><rect x={80 + i * 460} y={1610} width={140} height={22} rx={11} fill="#C9A23F" stroke="#7A5E1A" strokeWidth={3} /></g>)}
      {/* frascos y cables */}
      {[780, 880, 980].map((fx, i) => <Frasco key={i} x={fx} y={1250} viva={viva} />)}
      <path d="M 780 1096 C 700 1030 480 1080 374 1192" stroke="#1A1A22" strokeWidth={7} fill="none" strokeLinecap="round" />
      <path d="M 780 1096 C 700 1030 480 1080 374 1192" stroke="#FFE45A" strokeWidth={5} fill="none" strokeDasharray="12 40" strokeDashoffset={-s * 140} opacity={viva} />
      {/* interruptor de cuchilla */}
      <rect x={290} y={1200} width={96} height={22} rx={6} fill="#B8BCC4" stroke="#5A5E68" strokeWidth={4} />
      <circle cx={374} cy={1196} r={9} fill="#C98A3A" />
      <g transform={`rotate(${-abierto * 62} 304 1196)`}><rect x={300} y={1188} width={76} height={11} rx={4} fill="#D9B24A" stroke="#7A5E1A" strokeWidth={3} /><rect x={296} y={1170} width={12} height={30} rx={4} fill="#2A160A" /></g>
      <path d="M 300 1196 C 250 1240 340 1265 420 1236" stroke="#1A1A22" strokeWidth={7} fill="none" strokeLinecap="round" />
      <Llave x={500} y={1250} tap={tap} />
      <Chisp x={600} y={1150} on={tap * (v === 1 ? lin(1.0, 1.4, 0.3, 1) : 1)} n={v === 1 ? 6 : 8} r={v === 1 ? 70 : 90} />
      {v === 2 && <>
        <path d={wire} stroke="#1A1A22" strokeWidth={8} fill="none" strokeLinecap="round" strokeLinejoin="round" />
        <path d={wire} stroke={AZUL} strokeWidth={14} fill="none" opacity={0.25 * lin(T2 + 0.5, T2 + 1.5, 0, 1)} strokeLinecap="round" />
        <path d={wire} stroke="#DFF6FF" strokeWidth={5} fill="none" strokeDasharray="26 16 70 16 26 44" strokeDashoffset={-s * 300} opacity={lin(T2 + 0.5, T2 + 1.5, 0, 1)} strokeLinecap="round" />
        <Recorrido puntos={chPath} t0={T2 + 0.3} t1={TORM1 - 0.1} color="rgba(120,215,255,0.8)" render={(x, y) => <Chispa x={x} y={y} sc={0.55} />} />
        {s > TORM1 - 0.1 && <Chispa x={520} y={1170} sc={0.6 + 0.12 * Math.sin(s * 6)} />}
        <Ondas x={520} y={1190} t0={TORM1} color={AZUL_C} radio={360} />
      </>}
      {v === 3 && <>
        <Chispa x={500 + 20 * Math.sin(s * 2)} y={1090 + 12 * Math.sin(s * 3)} sc={0.58 + (s > BAT2 ? 0.14 * Math.abs(Math.sin(s * 6)) : 0)} />
        <Ondas x={540} y={930} t0={FUNC} color="#FFF3B0" radio={360} />
      </>}
    </Lugar>
  );
};

// ---------- E2: el Sol enorme tras la ventana ----------
const SolVentana: React.FC = () => {
  const {s, spr} = useS();
  const pop = spr(SOL1, 9, 130);
  return (
    <Lugar tipo="papel" base="radial-gradient(circle at 62% 40%, #FFE08A 0%, #FF8A2A 48%, #6A2008 100%)" linea="rgba(120,40,10,0.35)" luz="rgba(255,220,120,0.3)" semilla={31} bx={760} by={820} bc="rgba(255,190,90,0.7)"
      paradas={[{t: LA - 0.1, x: 300, y: 950, zoom: 1.0}, {t: SOL1 - 0.4, x: 600, y: 900, zoom: 1.2}, {t: SOL1 + 1.4, x: 720, y: 860, zoom: 1.45}]}>
      <defs><radialGradient id="solG" cx="50%" cy="50%" r="50%"><stop offset="0%" stopColor="#FFF6B0" /><stop offset="55%" stopColor="#FFC040" /><stop offset="100%" stopColor="#FF7A1A" /></radialGradient></defs>
